import {canBid} from './engine.js';
import {jokerButton} from './joker-ui.js';
export function createAuctionUI({esc,photo,photoNote,cardInfo,timerUI,activityUI}){
 function stars(deal){return `<span class="deal-stars" aria-label="F/P ${deal.stars}/5"><span>${'★'.repeat(deal.stars)}</span><span class="empty-stars">${'★'.repeat(5-deal.stars)}</span></span>`;}
 function receipt(g,{compact=false,canNext=false}={}){
  const sale=g.lastSale;if(!sale)return '';const winner=g.players.find(p=>p.id===sale.playerId),deal=g.settings.pricePerformance?sale.card.deal:null;
  return `<section class="sale-receipt ${compact?'compact':''}" aria-label="Son açık artırmanın sonucu"><div class="receipt-heading"><span class="sale-check" aria-hidden="true">✓</span><span class="eyebrow">${compact?'Son kart da sahibini buldu':'Açık artırma tamamlandı'}</span></div><h2>${esc(sale.name)} aldı!</h2><p class="sale-card-name">${esc(sale.card.name)} artık kadrosunda.</p><div class="sale-numbers"><div><small>Ödenen</small><strong>${sale.card.paid}<span> jeton</span></strong></div><div><small>Kalan bütçe</small><strong>${sale.remainingBudget??winner?.budget}<span> jeton</span></strong></div></div>${deal?`<div class="deal-rating"><div><span class="deal-tag">F/P</span>${stars(deal)}</div><strong>${esc(deal.label)}</strong><details><summary>Yıldızlar neye göre?</summary><p>Kartın bu kategorideki oyun değeri ve başlangıç bütçesiyle hesaplanan referans fiyatı yaklaşık <strong>${deal.referencePrice} jeton</strong>. ${sale.card.paid} jetona aldın. Fiyat düşük kaldıkça yıldız artar; bu değerlendirme kadro veya seri puanına eklenmez.</p></details></div>`:''}${!compact?canNext?'<button class="btn lime wide next-card" data-action="next">Sıradaki kartı aç <span aria-hidden="true">→</span></button>':'<p class="receipt-wait">Oda sahibi sıradaki kartı açacak.</p>':''}</section>`;
 }
 function stage(g,c,{cap,canNext,busy,connectionError,flash,you,shared=false,actorId=null}){
  const sold=g.status==='sold',opening=g.price===0,leader=g.players.find(p=>p.id===g.leaderId),opener=g.players.find(p=>p.id===g.turnId),actor=g.players.find(p=>p.id===actorId),ready=canBid(g,actorId),locked=busy||connectionError;
  const title=sold?g.lastSale.name:opening?opener?.name:'Artıran var mı?';
  const hint=opening?(ready?'İlk teklif senden. Sayaç teklif verince başlar.':`${opener?.name} 1 jetonla açacak.`):shared&&!actor?'Artırmak veya çekilmek için ismini seç.':ready?`Sıra bekleme; en fazla ${cap} jeton verebilirsin.`:actor?.id===g.leaderId?'Teklifin önde. Başka biri artırırsa tekrar teklif verebilirsin.':actor?.cards.length===g.settings.slots?'Kadron tamamlandı.':'Çekildin veya bütçen bu teklif için yetmiyor.';
  const wallet=shared&&!opening?`<div class="bid-wallet bidder-picker"><label for="bidder-select">Teklif veren</label><select id="bidder-select" name="bidderId" aria-label="Teklif verecek oyuncu"><option value="">İsmini seç</option>${g.players.filter(p=>canBid(g,p.id)).map(p=>`<option value="${esc(p.id)}" ${actorId===p.id?'selected':''}>${esc(p.name)} · ${p.budget} jeton</option>`).join('')}</select></div>`:`<div class="bid-wallet"><span>${actor?esc(actor.name)+' · Kalan bütçe':'Açılış bekleniyor'}</span><strong>${actor?.budget??'—'} <small>jeton</small></strong></div>`;
  return `<section class="auction-play ${sold?'is-sold':''}"><div class="turn-spotlight ${sold?'settled':ready?'your-turn':''} ${flash?'turn-enter':''}" role="status"><span class="spotlight-avatar" aria-hidden="true">${sold?'✓':opening?esc(opener?.name[0]):'↗'}</span><div><small>${sold?'Kart sahibini buldu':opening?'İlk teklif sırası':'Serbest artırma'}</small><strong>${esc(title)}${opening&&you===opener?.id?' · Sen':''}</strong></div><span class="turn-badge">${sold?'Tamamlandı':opening?'Açılış · 1 jeton':`Yeni teklif · ${g.price+1} jeton`}</span></div>
  <div class="auction-layout"><section class="auction-stage"><div class="stage-heading"><span>${esc(c.name)}</span><span>Kart <strong>${g.index+1}</strong> / ${g.totalCards}</span></div><article class="auction-card" aria-label="Açık artırmadaki kart"><div class="card-top"><span>${esc(g.current.universe||c.group)}</span><span>${sold?'KADROYA KATILDI':'AÇIK ARTIRMA'}</span></div>${photo(g.current,'auction-photo',true)}${photoNote(g.current)}<div class="auction-caption"><h1>${esc(g.current.name)}</h1><p class="card-description">${esc(cardInfo(g.current).text)}</p></div></article>${sold?`<div class="stage-sold"><span aria-hidden="true">✓</span> ${esc(g.lastSale.name)} · ${g.price} jeton</div>`:`<div class="auction-price"><div><small>${opening?'Başlangıç fiyatı':'En yüksek teklif'}</small><strong>${opening?1:g.price}<span> jeton</span></strong></div><span class="bid-owner">${leader?`<span class="leader-dot"></span>${esc(leader.name)} önde`:'İlk teklif bekleniyor'}</span></div>${timerUI(g)}`}</section>
  <aside class="auction-controls">${sold?receipt(g,{canNext}):`<section class="auction-action-panel"><span class="eyebrow">${opening?'İlk teklif':leader?.id===actorId?'Teklifin önde':'İsteyen artırabilir'}</span><h2>${esc(actor?.name||(shared?'Kim artırıyor?':opener?.name))}</h2><p class="action-question">${opening?'Açık artırma 1 jetonla başlar.':'Sıra yok. Süre dolmadan teklifini ver.'}</p>${wallet}<button class="btn lime wide bid-main" data-action="bid" data-amount="${g.price+1}" ${!ready||locked?'disabled':''}><span>${opening?'1 jetonla başlat':'+1 artır'}</span>${opening?'':`<strong>${g.price+1} jeton</strong>`}</button>${jokerButton(g,actor,{mine:ready,busy,connectionError,className:'wide bid-pass'})||`<button class="btn ghost wide bid-pass" data-action="pass" ${!ready||opening||locked?'disabled':''}>Bu karttan çekil</button>`}<p class="action-hint">${esc(hint)}</p></section>`}${activityUI(g)}</aside></div>
  <div class="bidder-row" aria-label="Oyuncuların açık artırma durumu">${g.players.map(p=>{const state=sold?p.id===g.lastSale.playerId?'Kartı aldı':'':p.cards.length===g.settings.slots?'Kadrosu doldu':opening&&p.id===g.turnId?'İlk teklif':p.id===g.leaderId?'Önde':canBid(g,p.id)?'Artırabilir':g.activeIds.includes(p.id)?'Açılışı bekliyor':'Bu kartta yok';return `<div class="bidder ${!sold&&opening&&p.id===g.turnId?'current':''} ${p.id===g.leaderId?'leading':''}"><span class="avatar" aria-hidden="true">${esc(p.name[0])}</span><span><strong>${esc(p.name)}</strong><small>${p.budget} jeton · ${p.cards.length}/${g.settings.slots} kart</small></span><span class="bidder-state">${state}</span></div>`;}).join('')}</div><div class="mobile-table-tools"><button data-action="table-details">Kart bilgisi ve kadrolar <span aria-hidden="true">↗</span></button></div></section>`;
 }
 return {stage,receipt};
}
